import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {prepare} from '../../../static/inverse/core/engine.js';
import {readHardPhoto} from '../../../scripts/inverse/hard-photo-data.mjs';
import {hardPhotoTarget} from '../../../scripts/inverse/hard-photo-target.mjs';
const root=new URL('.',import.meta.url),read=async p=>JSON.parse(await fs.readFile(p));
const sha=b=>createHash('sha256').update(b).digest('hex');
const inputs=await read(new URL('inputs.json',root)),pins=await read(new URL('source.json',root));
for(const[p,h]of Object.entries(pins))assert.equal(sha(await fs.readFile(p)),h,p);
const photo=await readHardPhoto(inputs.source),results=[];
for(const row of inputs.rows){
  const imported=prepare({...photo,quad:row.quad},row.settings);
  const target=hardPhotoTarget(imported,'mask',row.settings),source=target.sourceImage;
  const maskSha256=sha(source.mask),validSha256=source.validMask?sha(source.validMask):null;
  if(row.variant==='saved-automatic'){
    assert.equal(maskSha256,row.expectedMaskSha256,row.id+' must reproduce the corpus mask exactly');
    assert.equal(validSha256,row.expectedValidSha256,row.id+' must reproduce observation coverage exactly');
  }
  results.push({id:row.id,variant:row.variant,maskSha256,validSha256,
    observedPixels:source.validMask?.reduce((a,b)=>a+b,0)??source.mask.length,totalPixels:source.mask.length});
}
await fs.writeFile(new URL('preflight.json',root),JSON.stringify({status:'passed',results},null,2)+'\n');
console.log('All four targets prepared; both saved automatic masks and coverage reproduce exactly.');
